WITH valid AS (SELECT id, customer_id, plan, start_date, monthly_fee, status, FLOOR(monthly_fee) AS monthly_fee_whole, CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END AS is_enterprise FROM subscriptions WHERE customer_id IS NOT NULL AND start_date > TO_DATE('2023-06-18')) SELECT src.*, sub.id AS subscription_id, sub.plan AS subscription_plan, sub.monthly_fee AS subscription_monthly_fee FROM valid src LEFT JOIN subscriptions sub ON src.customer_id = sub.customer_id AND src.start_date >= sub.start_date AND src.start_date < sub.end_date + INTERVAL '30' DAY;
